from PIL import Image, ImageDraw
import os

def find_bore(path):
    im = Image.open(path)
    w,h = im.size
    px = im.load()
    pts=[]
    for y in range(h):
        for x in range(w):
            p=px[x,y]
            g=(p[0]+p[1]+p[2])/3
            if g<70:
                # exclude huge gripper: check if this pixel is in a region that's not the main gripper
                pts.append((x,y))
    # The gripper is a large connected dark region from the top. The bore is a small blob.
    # Use a simple approach: dark pixels whose local window isn't mostly dark (isolated)
    # Faster: scan for dark pixels with light pixel above within 40px and not part of top blob
    # Flood-fill from top dark pixels to mark gripper
    visited=[[False]*w for _ in range(h)]
    from collections import deque
    q=deque()
    for x in range(w):
        p=px[x,0]
        if (p[0]+p[1]+p[2])/3 < 80:
            q.append((x,0)); visited[0][x]=True
        p=px[x,1]
        if (p[0]+p[1]+p[2])/3 < 80:
            q.append((x,1)); visited[1][x]=True
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    while q:
        x,y=q.popleft()
        for dx,dy in dirs:
            nx,ny=x+dx,y+dy
            if 0<=nx<w and 0<=ny<h and not visited[ny][nx]:
                p=px[nx,ny]
                if (p[0]+p[1]+p[2])/3 < 90:
                    visited[ny][nx]=True
                    q.append((nx,ny))
    bore=[]
    for y in range(h):
        for x in range(w):
            if visited[y][x]:
                continue
            p=px[x,y]
            if (p[0]+p[1]+p[2])/3 < 80:
                bore.append((x,y))
    if not bore:
        return None
    xs=[p[0] for p in bore]; ys=[p[1] for p in bore]
    return dict(n=len(bore), xmin=min(xs), xmax=max(xs), ymin=min(ys), ymax=max(ys),
                cx=sum(xs)/len(xs), cy=sum(ys)/len(ys))

